package scalus.uplc.eval

import scalus.uplc.builtin.{platform, PlatformSpecific, given}
import scalus.cardano.ledger.{CardanoInfo, Language, MajorProtocolVersion}
import scalus.uplc.*

/** Plutus VM facade.
  *
  *   - Term is a representation of a UPLC term.
  *   - Term can be named, debruijned, or both.
  *   - Term can be evaluated by [[CekMachine]]
  *   - Program is a versioned UPLC term. 1.0.0 for Plutus V1 and V2, 1.1.0 for Plutus V3.
  *   - Plutus Script is a UPLC Program that should be evaluated according to the Plutus
  *     specification. This includes CIP-117.
  *
  * @param language
  *   The Plutus version
  * @param machineParams
  *   The machine parameters
  * @param semanticVariant
  *   The builtin semantics variant
  * @param platformSpecific
  *   The platform specific implementation of certain functions used by VM builtins
  */
class PlutusVM(
    val language: Language,
    val machineParams: MachineParams,
    val semanticVariant: BuiltinSemanticsVariant,
    platformSpecific: PlatformSpecific,
    val protocolVersion: MajorProtocolVersion = MajorProtocolVersion.changPV
) {
    private val builtins = new CardanoBuiltins(
      machineParams.builtinCostModel,
      platformSpecific,
      semanticVariant
    )

    private val caseOnBuiltinsEnabled: Boolean =
        protocolVersion >= MajorProtocolVersion.vanRossemPV || language == Language.PlutusV4

    /** Evaluates a Plutus script according to the Plutus specification.
      *
      * This includes CIP-117.
      *
      * @param program
      *   The Plutus script
      * @param budgetSpender
      *   The budget spender
      * @param logger
      *   The logger
      * @return
      *   The result of the evaluation. Must be `Unit` for Plutus V3.
      * @throws RuntimeException
      *   if the result is not valid
      */
    def evaluateScript(
        program: DeBruijnedProgram,
        budgetSpender: BudgetSpender,
        logger: Logger
    ): Term = {
        val result = evaluateDeBruijnedTerm(program.term, budgetSpender, logger)
        if isResultValid(result) then result
        else throw new InvalidReturnValue(result)
    }

    /** Evaluates a Plutus script according to the Plutus specification.
      *
      * This includes CIP-117.
      *
      * @param program
      *   The Plutus script
      * @return
      *   The result of the evaluation
      */
    def evaluateScriptDebug(program: DeBruijnedProgram): Result =
        runWithBudgetTracking(program.term, validateResult = true)

    /** Evaluates a Plutus script with profiling enabled.
      *
      * Like [[evaluateScriptDebug]] but also collects profiling data by source location and
      * function. Access profiling data via `result.profile`.
      *
      * @param program
      *   The Plutus script
      * @return
      *   Result with `profile` set
      */
    def evaluateScriptProfile(program: DeBruijnedProgram): Result =
        runWithBudgetTracking(program.term, profiling = true, validateResult = true)

    /** Evaluates a debruijned term using the CEK machine. This method does not follow CIP-117.
      *
      * @param debruijnedTerm
      *   The debruijned term
      * @param budgetSpender
      *   The budget spender
      * @param logger
      *   The logger
      * @return
      *   The evaluated term
      * @throws RuntimeException
      */
    def evaluateDeBruijnedTerm(
        debruijnedTerm: Term,
        budgetSpender: BudgetSpender = NoBudgetSpender,
        logger: Logger = NoLogger
    ): Term = {
        val cek = new CekMachine(
          machineParams,
          budgetSpender,
          logger,
          builtins.getBuiltinRuntime,
          caseOnBuiltinsEnabled
        )
        DeBruijn.fromDeBruijnTerm(cek.evaluateTerm(debruijnedTerm))
    }

    /** Evaluates a debruijned term with profiling enabled. Does not follow CIP-117.
      *
      * Like [[evaluateDeBruijnedTerm]] but also collects profiling data. Access profiling data via
      * `result.profile`.
      *
      * @param debruijnedTerm
      *   The debruijned term
      * @return
      *   Result with `profile` set
      */
    def evaluateDeBruijnedTermProfile(debruijnedTerm: Term): Result =
        runWithBudgetTracking(debruijnedTerm, profiling = true)

    private def runWithBudgetTracking(
        debruijnedTerm: Term,
        profiling: Boolean = false,
        validateResult: Boolean = false
    ): Result = {
        val spenderLogger = TallyingBudgetSpenderLogger(CountingBudgetSpender())
        val cek = new CekMachine(
          machineParams,
          spenderLogger,
          spenderLogger,
          builtins.getBuiltinRuntime,
          caseOnBuiltinsEnabled,
          profiling = profiling
        )
        try
            val term = DeBruijn.fromDeBruijnTerm(cek.evaluateTerm(debruijnedTerm))
            if validateResult && !isResultValid(term) then throw new InvalidReturnValue(term)
            Result.Success(
              term,
              spenderLogger.getSpentBudget,
              spenderLogger.costs.toMap,
              spenderLogger.getLogsWithBudget,
              profile = cek.getProfile
            )
        catch
            case e: Exception =>
                Result.Failure(
                  e,
                  spenderLogger.getSpentBudget,
                  spenderLogger.costs.toMap,
                  spenderLogger.getLogsWithBudget,
                  profile = cek.getProfile
                )
    }

    /** Plutus V3 and V4 require the result to be `Unit` to be considered valid.
      * @param res
      *   The result term
      * @return
      *   `true` if the result is valid, `false` otherwise
      *
      * @see
      *   [CIP-117](https://cips.cardano.org/cip/CIP-0117/)
      */
    private def isResultValid(res: Term): Boolean = (language, res) match
        case (Language.PlutusV1 | Language.PlutusV2, _)                            => true
        case (Language.PlutusV3 | Language.PlutusV4, Term.Const(Constant.Unit, _)) => true
        case _                                                                     => false
}

/** Companion object for PlutusVM that provides factory methods for creating VM instances for
  * different Plutus versions (V1, V2, V3, V4).
  */
object PlutusVM {

    /** Creates a Plutus V1 VM with custom parameters.
      *
      * @param params
      *   Custom machine parameters to use for the VM
      * @return
      *   A configured Plutus V1 VM instance
      */
    def makePlutusV1VM(params: MachineParams): PlutusVM =
        makePlutusV1VM(params, CardanoInfo.mainnet.majorProtocolVersion)

    /** Creates a Plutus V1 VM with default parameters.
      *
      * @return
      *   A Plutus V1 VM instance with default post-Conway parameters
      */
    def makePlutusV1VM(): PlutusVM = {
        val params = MachineParams.fromProtocolParams(
          CardanoInfo.mainnet.protocolParams,
          Language.PlutusV1
        )
        makePlutusV1VM(params)
    }

    /** Creates a Plutus V1 VM with custom parameters and a specific protocol version.
      *
      * Use `MajorProtocolVersion.vanRossemPV` to enable protocol version 11 features
      * (case-on-builtins, batch6 builtins like ExpModInteger).
      *
      * @param params
      *   Custom machine parameters to use for the VM
      * @param protocolVersion
      *   The target protocol version
      * @return
      *   A configured Plutus V1 VM instance
      */
    def makePlutusV1VM(params: MachineParams, protocolVersion: MajorProtocolVersion): PlutusVM = {
        val semanticVariant = BuiltinSemanticsVariant.fromProtocolAndPlutusVersion(
          protocolVersion,
          Language.PlutusV1
        )
        new PlutusVM(
          Language.PlutusV1,
          params,
          semanticVariant,
          platform,
          protocolVersion
        )
    }

    /** Creates a Plutus V1 VM with default parameters and a specific protocol version.
      *
      * Use `MajorProtocolVersion.vanRossemPV` to enable protocol version 11 features
      * (case-on-builtins, batch6 builtins like ExpModInteger).
      *
      * @param protocolVersion
      *   The target protocol version
      * @return
      *   A Plutus V1 VM instance with default parameters
      */
    def makePlutusV1VM(protocolVersion: MajorProtocolVersion): PlutusVM = {
        val params = MachineParams.defaultParamsFor(Language.PlutusV1, protocolVersion)
        makePlutusV1VM(params, protocolVersion)
    }

    /** Creates a Plutus V2 VM with custom parameters.
      *
      * @param params
      *   Custom machine parameters to use for the VM
      * @return
      *   A configured Plutus V2 VM instance
      */
    def makePlutusV2VM(params: MachineParams): PlutusVM =
        makePlutusV2VM(params, CardanoInfo.mainnet.majorProtocolVersion)

    /** Creates a Plutus V2 VM with default parameters.
      *
      * @return
      *   A Plutus V2 VM instance with default post-Conway parameters
      */
    def makePlutusV2VM(): PlutusVM = {
        val params = MachineParams.fromProtocolParams(
          CardanoInfo.mainnet.protocolParams,
          Language.PlutusV2
        )
        makePlutusV2VM(params)
    }

    /** Creates a Plutus V2 VM with custom parameters and a specific protocol version.
      *
      * Use `MajorProtocolVersion.vanRossemPV` to enable protocol version 11 features
      * (case-on-builtins, batch6 builtins like ExpModInteger).
      *
      * @param params
      *   Custom machine parameters to use for the VM
      * @param protocolVersion
      *   The target protocol version
      * @return
      *   A configured Plutus V2 VM instance
      */
    def makePlutusV2VM(params: MachineParams, protocolVersion: MajorProtocolVersion): PlutusVM = {
        val semanticVariant = BuiltinSemanticsVariant.fromProtocolAndPlutusVersion(
          protocolVersion,
          Language.PlutusV2
        )
        new PlutusVM(
          Language.PlutusV2,
          params,
          semanticVariant,
          platform,
          protocolVersion
        )
    }

    /** Creates a Plutus V2 VM with default parameters and a specific protocol version.
      *
      * Use `MajorProtocolVersion.vanRossemPV` to enable protocol version 11 features
      * (case-on-builtins, batch6 builtins like ExpModInteger).
      *
      * @param protocolVersion
      *   The target protocol version
      * @return
      *   A Plutus V2 VM instance with default parameters
      */
    def makePlutusV2VM(protocolVersion: MajorProtocolVersion): PlutusVM = {
        val params = MachineParams.defaultParamsFor(Language.PlutusV2, protocolVersion)
        makePlutusV2VM(params, protocolVersion)
    }

    /** Creates a Plutus V3 VM with custom parameters.
      *
      * @param params
      *   Custom machine parameters to use for the VM
      * @return
      *   A configured Plutus V3 VM instance
      */
    def makePlutusV3VM(params: MachineParams): PlutusVM = {
        val semanticVariant = BuiltinSemanticsVariant.fromProtocolAndPlutusVersion(
          CardanoInfo.mainnet.majorProtocolVersion,
          Language.PlutusV3
        )
        new PlutusVM(
          Language.PlutusV3,
          params,
          semanticVariant,
          platform
        )
    }

    /** Creates a Plutus V3 VM with default parameters.
      *
      * @return
      *   A Plutus V3 VM instance with default parameters
      */
    def makePlutusV3VM(): PlutusVM = {
        val params = MachineParams.fromProtocolParams(
          CardanoInfo.mainnet.protocolParams,
          Language.PlutusV3
        )
        makePlutusV3VM(params)
    }

    /** Creates a Plutus V3 VM with a specific protocol version.
      *
      * Use `MajorProtocolVersion.vanRossemPV` to enable protocol version 11 features
      * (case-on-builtins, batch6 builtins like ExpModInteger).
      *
      * @param params
      *   Custom machine parameters to use for the VM
      * @param protocolVersion
      *   The target protocol version
      * @return
      *   A configured Plutus V3 VM instance
      */
    def makePlutusV3VM(params: MachineParams, protocolVersion: MajorProtocolVersion): PlutusVM = {
        val semanticVariant = BuiltinSemanticsVariant.fromProtocolAndPlutusVersion(
          protocolVersion,
          Language.PlutusV3
        )
        new PlutusVM(
          Language.PlutusV3,
          params,
          semanticVariant,
          platform,
          protocolVersion
        )
    }

    /** Creates a Plutus V3 VM with default parameters and a specific protocol version.
      *
      * Use `MajorProtocolVersion.vanRossemPV` to enable protocol version 11 features
      * (case-on-builtins, batch6 builtins like ExpModInteger).
      *
      * @param protocolVersion
      *   The target protocol version
      * @return
      *   A Plutus V3 VM instance with default parameters
      */
    def makePlutusV3VM(protocolVersion: MajorProtocolVersion): PlutusVM = {
        val params = MachineParams.defaultParamsFor(Language.PlutusV3, protocolVersion)
        makePlutusV3VM(params, protocolVersion)
    }

    /** Creates a Plutus V4 VM with custom parameters.
      *
      * @deprecated
      *   Use makePlutusV3VM(params, MajorProtocolVersion.vanRossemPV) instead. There is no PlutusV4
      *   in Cardano.
      */
    @deprecated("Use makePlutusV3VM(params, MajorProtocolVersion.vanRossemPV) instead", "0.15.1")
    def makePlutusV4VM(params: MachineParams): PlutusVM = {
        makePlutusV3VM(params, MajorProtocolVersion.vanRossemPV)
    }

    /** Creates a Plutus V4 VM with default parameters.
      *
      * @deprecated
      *   Use makePlutusV3VM(MajorProtocolVersion.vanRossemPV) instead. There is no PlutusV4 in
      *   Cardano.
      */
    @deprecated("Use makePlutusV3VM(MajorProtocolVersion.vanRossemPV) instead", "0.15.1")
    def makePlutusV4VM(): PlutusVM = {
        makePlutusV3VM(MajorProtocolVersion.vanRossemPV)
    }
}
