/** Base class for case-on-builtin errors (PlutusV4+) */
abstract class CaseOnBuiltinError(
    msg: String,
    env: CekValEnv,
    sourcePos: ScalusSourcePos = ScalusSourcePos.empty
) extends StackTraceMachineError(msg, env, sourcePos)

