    val index: BigInt,
    val branchCount: Int,
    env: CekValEnv,
    sourcePos: ScalusSourcePos = ScalusSourcePos.empty
) extends CaseOnBuiltinError(
      s"Case index $index out of bounds for $branchCount branches",
      env,
      sourcePos
    )

