    val value: Boolean,
    val branchCount: Int,
    env: CekValEnv,
    sourcePos: ScalusSourcePos = ScalusSourcePos.empty
) extends CaseOnBuiltinError(
      s"Case on boolean $value requires ${
              if value then 2 else 1
          } branches, but only $branchCount provided",
      env,
      sourcePos
    )

