package scalus.cardano.ledger

import io.bullet.borer.*
import org.typelevel.paiges.Doc
import scalus.utils.{Pretty, Style}

case class TransactionBody(
    /** Transaction inputs to spend */
    inputs: TaggedSortedSet[TransactionInput],

    /** Transaction outputs to create */
    outputs: IndexedSeq[Sized[TransactionOutput]],

    /** Transaction fee */
    fee: Coin,

    /** Time-to-live (TTL) - transaction is invalid after this slot */
    ttl: Option[Long] = None,

    /** Certificates for delegation, stake operations, etc. */
    certificates: TaggedOrderedStrictSet[Certificate] = TaggedOrderedStrictSet.empty,

    /** Withdrawals from reward accounts */
    withdrawals: Option[Withdrawals] = None,

    /** Auxiliary data hash */
    auxiliaryDataHash: Option[AuxiliaryDataHash] = None,

    /** Transaction validity start (transaction is invalid before this slot) */
    validityStartSlot: Option[Long] = None,

    /** Minting operations */
    mint: Option[Mint] = None,

    /** Script data hash */
    scriptDataHash: Option[ScriptDataHash] = None,

    /** Collateral inputs */
    collateralInputs: TaggedSortedSet[TransactionInput] = TaggedSortedSet.empty,

    /** Required signers */
    requiredSigners: TaggedSortedSet[AddrKeyHash] = TaggedSortedSet.empty,

    /** Network ID */
    networkId: Option[Int] = None,

    /** Collateral return output */
    collateralReturnOutput: Option[Sized[TransactionOutput]] = None,

    /** Total collateral */
    totalCollateral: Option[Coin] = None,

    /** Reference inputs */
    referenceInputs: TaggedSortedSet[TransactionInput] = TaggedSortedSet.empty,

    /** Voting procedures */
    votingProcedures: Option[VotingProcedures] = None,

    /** Proposal procedures */
    proposalProcedures: TaggedOrderedSet[ProposalProcedure] = TaggedOrderedSet.empty,

    /** Transaction deposit */
    currentTreasuryValue: Option[Coin] = None,

    /** Transaction deposit return */
    donation: Option[Coin] = None
):
    /** Validate optional withdrawals */
    require(
      withdrawals.forall(_.withdrawals.nonEmpty),
      "If withdrawals are present, they must be non-empty"
    )

    /** Validate network ID if present */
    require(
      networkId.forall(id => id == 0 || id == 1),
      "Network ID must be 0 (testnet) or 1 (mainnet)"
    )

object TransactionBody:
    // Needed to resolve ambiguity between Encoder[TaggedSet] and Encoder[IndexedSeq]
    // we override it with explicit import which is higher priority in given resolution
//    import TaggedSet.given

    /** CBOR encoder for TransactionBody */
    given Encoder[TransactionBody] with
        def write(w: Writer, value: TransactionBody): Writer =
            // Count the number of fields to write
            var mapSize = 3 // inputs, outputs, fee are required

            if value.ttl.isDefined then mapSize += 1
            if value.certificates.toSeq.nonEmpty then mapSize += 1
            if value.withdrawals.isDefined then mapSize += 1
            if value.auxiliaryDataHash.isDefined then mapSize += 1
            if value.validityStartSlot.isDefined then mapSize += 1
            if value.mint.isDefined then mapSize += 1
            if value.scriptDataHash.isDefined then mapSize += 1
            if value.collateralInputs.toSet.nonEmpty then mapSize += 1
            if value.requiredSigners.toSet.nonEmpty then mapSize += 1
            if value.networkId.isDefined then mapSize += 1
            if value.collateralReturnOutput.isDefined then mapSize += 1
            if value.totalCollateral.isDefined then mapSize += 1
            if value.referenceInputs.toSet.nonEmpty then mapSize += 1
            if value.votingProcedures.isDefined then mapSize += 1
            if value.proposalProcedures.toSeq.nonEmpty then mapSize += 1
            if value.currentTreasuryValue.isDefined then mapSize += 1
            if value.donation.isDefined then mapSize += 1

            w.writeMapHeader(mapSize)

            // Required fields

            // Inputs (key 0)
            w.writeInt(0)
            w.write(value.inputs)

            // Outputs (key 1)
            w.writeInt(1)
            w.write(value.outputs)

            // Fee (key 2)
            w.writeInt(2)
            w.write(value.fee)

            // Optional fields

            // TTL (key 3)
            value.ttl.foreach { ttl =>
                w.writeInt(3)
                w.writeLong(ttl)
            }

            // Certificates (key 4)
            if value.certificates.toSeq.nonEmpty then
                w.writeInt(4)
                w.write(value.certificates)

            // Withdrawals (key 5)
            value.withdrawals.foreach { withdrawals =>
                w.writeInt(5)
                w.write(withdrawals)
            }

            // Auxiliary data hash (key 7)
            value.auxiliaryDataHash.foreach { hash =>
                w.writeInt(7)
                w.write(hash)
            }

            // Validity start slot (key 8)
            value.validityStartSlot.foreach { slot =>
                w.writeInt(8)
                w.writeLong(slot)
            }

            // Mint (key 9)
            value.mint.foreach { mint =>
                w.writeInt(9)
                w.write(mint)
            }

            // Script data hash (key 11)
            value.scriptDataHash.foreach { hash =>
                w.writeInt(11)
                w.write(hash)
            }

            // Collateral inputs (key 13)
            if value.collateralInputs.toSet.nonEmpty then
                w.writeInt(13)
                w.write(value.collateralInputs)

            if value.requiredSigners.toSet.nonEmpty then
                // Required signers (key 14)
                w.writeInt(14)
                w.write(value.requiredSigners)

            // Network ID (key 15)
            value.networkId.foreach { id =>
                w.writeInt(15)
                w.writeInt(id)
            }

            // Collateral return output (key 16)
            value.collateralReturnOutput.foreach { output =>
                w.writeInt(16)
                w.write(output)
            }

            // Total collateral (key 17)
            value.totalCollateral.foreach { coin =>
                w.writeInt(17)
                w.write(coin)
            }

            // Reference inputs (key 18)
            if value.referenceInputs.toSet.nonEmpty then
                w.writeInt(18)
                w.write(value.referenceInputs)

            // Voting procedures (key 19)
            value.votingProcedures.foreach { procedures =>
                w.writeInt(19)
                w.write(procedures)
            }

            // Proposal procedures (key 20)
            if value.proposalProcedures.toSeq.nonEmpty then
                w.writeInt(20)
                w.write(value.proposalProcedures)

            // Deposit (key 21)
            value.currentTreasuryValue.foreach { coin =>
                w.writeInt(21)
                w.write(coin)
            }

            // Deposit return (key 22)
            value.donation.foreach { coin =>
                if coin.nonZero then
                    w.writeInt(22)
                    w.write(coin)
            }

            w

    /** CBOR decoder for TransactionBody */
    given (using OriginalCborByteArray, ProtocolVersion): Decoder[TransactionBody] with
        def read(r: Reader): TransactionBody =
            val mapSize = r.readMapHeader()

            var inputs = TaggedSortedSet.empty[TransactionInput]
            var outputs = IndexedSeq.empty[Sized[TransactionOutput]]
            var fee: Option[Coin] = None
            var ttl: Option[Long] = None
            var certificates = TaggedOrderedStrictSet.empty[Certificate]
            var withdrawals: Option[Withdrawals] = None
            var auxiliaryDataHash: Option[AuxiliaryDataHash] = None
            var validityStartSlot: Option[Long] = None
            var mint: Option[Mint] = None
            var scriptDataHash: Option[ScriptDataHash] = None
            var collateralInputs = TaggedSortedSet.empty[TransactionInput]
            var requiredSigners = TaggedSortedSet.empty[AddrKeyHash]
            var networkId: Option[Int] = None
            var collateralReturnOutput: Option[Sized[TransactionOutput]] = None
            var totalCollateral: Option[Coin] = None
            var referenceInputs = TaggedSortedSet.empty[TransactionInput]
            var votingProcedures: Option[VotingProcedures] = None
            var proposalProcedures = TaggedOrderedSet.empty[ProposalProcedure]
            var currentTreasuryValue: Option[Coin] = None
            var donation: Option[Coin] = None

            var i = 0L
            while i < mapSize do
                val key = r.readInt()

                key match
                    case 0 => // Inputs
                        inputs = r.read[TaggedSortedSet[TransactionInput]]()

                    case 1 => // Outputs
                        outputs = r.read[IndexedSeq[Sized[TransactionOutput]]]()

                    case 2 => // Fee
                        fee = Some(r.read[Coin]())

                    case 3 => // TTL
                        if r.hasOverLong then ttl = Some(r.readOverLong())
                        else ttl = Some(r.readLong())
                    case 4 => // Certificates
                        certificates = r.read[TaggedOrderedStrictSet[Certificate]]()

                    case 5 => // Withdrawals
                        withdrawals = Some(r.read[Withdrawals]())

                    case 7 => // Auxiliary data hash
                        auxiliaryDataHash = Some(r.read[AuxiliaryDataHash]())

                    case 8 => // Validity start slot
                        validityStartSlot = Some(r.readLong())

                    case 9 => // Mint
                        mint = Some(r.read[Mint]())

                    case 11 => // Script data hash
                        scriptDataHash = Some(r.read[ScriptDataHash]())

                    case 13 => // Collateral inputs
                        collateralInputs = r.read[TaggedSortedSet[TransactionInput]]()

                    case 14 => // Required signers
                        requiredSigners = r.read[TaggedSortedSet[AddrKeyHash]]()

                    case 15 => // Network ID
                        val id = r.readInt()
                        if id != 0 && id != 1 then
                            r.validationFailure(s"Network ID must be 0 or 1, got $id")
                        networkId = Some(id)

                    case 16 => // Collateral return output
                        collateralReturnOutput = Some(r.read[Sized[TransactionOutput]]())

                    case 17 => // Total collateral
                        totalCollateral = Some(r.read[Coin]())

                    case 18 => // Reference inputs
                        referenceInputs = r.read[TaggedSortedSet[TransactionInput]]()

                    case 19 => // Voting procedures
                        votingProcedures = Some(r.read[VotingProcedures]())

                    case 20 => // Proposal procedures
                        proposalProcedures = r.read[TaggedOrderedSet[ProposalProcedure]]()
                    case 21 => // Deposit
                        currentTreasuryValue = Some(r.read[Coin]())

                    case 22 => // Deposit return
                        val value = r.read[Coin]()
                        if value == Coin.zero then r.validationFailure("Donation cannot be zero")
                        donation = Some(value)

                    case _ =>
                        r.validationFailure(s"Unknown key $key in TransactionBody")
                i += 1
            end while
            TransactionBody(
              inputs = inputs,
              outputs = outputs,
              fee = fee.get,
              ttl = ttl,
              certificates = certificates,
              withdrawals = withdrawals,
              auxiliaryDataHash = auxiliaryDataHash,
              validityStartSlot = validityStartSlot,
              mint = mint,
              scriptDataHash = scriptDataHash,
              collateralInputs = collateralInputs,
              requiredSigners = requiredSigners,
              networkId = networkId,
              collateralReturnOutput = collateralReturnOutput,
              totalCollateral = totalCollateral,
              referenceInputs = referenceInputs,
              votingProcedures = votingProcedures,
              proposalProcedures = proposalProcedures,
              currentTreasuryValue = currentTreasuryValue,
              donation = donation
            )

    import Doc.*
    import Pretty.formatAda

    /** Pretty prints TransactionBody with multi-line structured output */
    given Pretty[TransactionBody] with
        def pretty(a: TransactionBody, style: Style): Doc =
            def inputDoc(i: TransactionInput) = Pretty[TransactionInput].pretty(i, style)
            def outputDoc(o: TransactionOutput) = Pretty[TransactionOutput].pretty(o, style)
            def certDoc(c: Certificate) = Pretty[Certificate].pretty(c, style)

            val inputsDoc = Pretty.bulletList("inputs", a.inputs.toSet.toList.map(inputDoc))

            val outputsDoc =
                if a.outputs.nonEmpty then
                    text("outputs:") / stack(a.outputs.zipWithIndex.map { case (o, idx) =>
                        (text(s"[$idx]") & outputDoc(o.value)).hang(2)
                    }).indent(2)
                else empty

            val feeDoc = text("fee:") & Pretty[Coin].pretty(a.fee, style)

            val ttlDoc = a.ttl.fold(empty)(t => line + text(s"ttl: $t"))
            val validityStartDoc =
                a.validityStartSlot.fold(empty)(s => line + text(s"validityStart: $s"))
            val mintDoc =
                a.mint.fold(empty)(m => line + text("mint:") & Pretty[MultiAsset].pretty(m, style))

            val certificatesDoc =
                Pretty.bulletList("certificates", a.certificates.toSeq.toList.map(certDoc))
            val certificatesPrefixed =
                if a.certificates.toSeq.nonEmpty then line + certificatesDoc else empty

            val withdrawalsDoc = a.withdrawals.fold(empty) { w =>
                val entries = w.withdrawals.toList.map { case (ra, coin) =>
                    val addrStr = ra.address.toBech32.getOrElse(ra.address.toHex)
                    text(addrStr) + text(" -> ") + text(formatAda(coin.value))
                }
                if entries.nonEmpty then
                    line + text("withdrawals:") / stack(entries.map(text("- ") + _)).indent(2)
                else empty
            }

            val auxiliaryDataHashDoc =
                a.auxiliaryDataHash.fold(empty)(h => line + text(s"auxiliaryDataHash: ${h.toHex}"))

            val scriptDataHashDoc =
                a.scriptDataHash.fold(empty)(h => line + text(s"scriptDataHash: ${h.toHex}"))

            val refInputsDoc =
                Pretty.bulletList("referenceInputs", a.referenceInputs.toSet.toList.map(inputDoc))

            val collateralDoc =
                Pretty.bulletList("collateral", a.collateralInputs.toSet.toList.map(inputDoc))

            val refInputsPrefixed =
                if a.referenceInputs.toSet.nonEmpty then line + refInputsDoc else empty
            val collateralPrefixed =
                if a.collateralInputs.toSet.nonEmpty then line + collateralDoc else empty

            val requiredSignersDoc =
                if a.requiredSigners.toSet.nonEmpty then
                    line + Pretty.bulletList(
                      "requiredSigners",
                      a.requiredSigners.toSet.toList.map(h => text(h.toHex))
                    )
                else empty

            val networkIdDoc = a.networkId.fold(empty)(id => line + text(s"networkId: $id"))

            val collateralReturnDoc = a.collateralReturnOutput.fold(empty) { out =>
                line + text("collateralReturn:") & outputDoc(out.value)
            }

            val totalCollateralDoc = a.totalCollateral.fold(empty) { c =>
                line + text(s"totalCollateral: ${formatAda(c.value)}")
            }

            val votingProceduresDoc = a.votingProcedures.fold(empty) { vp =>
                val entries = vp.procedures.toList.flatMap { case (voter, actions) =>
                    actions.toList.map { case (govActionId, procedure) =>
                        val voterStr = voter match
                            case Voter.ConstitutionalCommitteeHotKey(kh) =>
                                s"CommitteeHotKey(${kh.toHex.take(16)}...)"
                            case Voter.ConstitutionalCommitteeHotScript(sh) =>
                                s"CommitteeHotScript(${sh.toHex.take(16)}...)"
                            case Voter.DRepKey(kh)        => s"DRepKey(${kh.toHex.take(16)}...)"
                            case Voter.DRepScript(sh)     => s"DRepScript(${sh.toHex.take(16)}...)"
                            case Voter.StakingPoolKey(kh) => s"PoolKey(${kh.toHex.take(16)}...)"
                        val actionStr =
                            s"${govActionId.transactionId.toHex.take(16)}...#${govActionId.govActionIndex}"
                        text(s"$voterStr on $actionStr: ${procedure.vote}")
                    }
                }
                if entries.nonEmpty then
                    line + text("votingProcedures:") / stack(entries.map(text("- ") + _)).indent(2)
                else empty
            }

            val proposalProceduresDoc =
                if a.proposalProcedures.toSeq.nonEmpty then
                    val entries = a.proposalProcedures.toSeq.toList.map { p =>
                        text(s"deposit=${formatAda(p.deposit.value)}, action=${p.govAction}")
                    }
                    line + text("proposalProcedures:") / stack(entries.map(text("- ") + _))
                        .indent(2)
                else empty

            val currentTreasuryValueDoc = a.currentTreasuryValue.fold(empty) { c =>
                line + text(s"currentTreasuryValue: ${formatAda(c.value)}")
            }

            val donationDoc = a.donation.fold(empty) { c =>
                line + text(s"donation: ${formatAda(c.value)}")
            }

            (inputsDoc / outputsDoc / feeDoc + ttlDoc + validityStartDoc + mintDoc +
                certificatesPrefixed + withdrawalsDoc + auxiliaryDataHashDoc + scriptDataHashDoc +
                refInputsPrefixed + collateralPrefixed + requiredSignersDoc + networkIdDoc +
                collateralReturnDoc + totalCollateralDoc + votingProceduresDoc +
                proposalProceduresDoc + currentTreasuryValueDoc + donationDoc).grouped
